mapper.select:
select * from member_order_info where deleted = 0 and status in (0,1) and end_time>now() and room_id in
#{item}
order by order_id asc

select *
from member_order_info
where deleted = 0
  and user_id = #{userId}
  and status = #{status}

select c.clear_id, o.order_id, o.order_no, o.store_id, s.store_name, o.room_id, r.room_name, r.type roomType, o.end_time orderEndTime, c.status, c.start_time, c.finish_time from member_clear_info c left join member_store_info s ON s.store_id = c.store_id left join member_order_info o ON c.order_id = o.order_id left join member_room_info r ON r.room_id = o.room_id where o.deleted = 0 and o.status in(1,2)
and o.store_id=#{storeId}
and c.user_id=#{userId}
and to_days(o.create_time) >= to_days(#{startTime}) and to_days(o.create_time) <= to_days(#{endTime})
and c.status=#{status}
order by create_time desc

select o.order_id , o.order_no , s.store_id , s.store_name , r.room_id , r.price , r.type roomType , r.room_name , o.user_id , m.nickname , o.start_time as startTime , o.end_time , ROUND(TIMESTAMPDIFF(SECOND, o.start_time,o.end_time) / 3600, 1) AS orderHour , o.pay_price , o.refund_price , o.status , o.create_time as createTime from member_order_info o left join member_store_info s ON o.store_id = s.store_id left join member_room_info r ON r.room_id = o.room_id left join member_user m ON m.id = o.user_id where o.deleted = 0
and o.user_id=#{userId}
and o.store_id in (${storeIds})
and o.status=#{status}
order by ${orderColumn} desc
order by o.order_id desc

select o.order_id , o.order_no , r.room_name , r.price roomPrice , o.room_id , o.store_id , r.type roomType , s.store_name , s.lat , s.lon , s.address , o.user_id , o.start_time , o.end_time , ROUND(TIMESTAMPDIFF(SECOND, o.start_time,o.end_time) / 3600, 1) AS orderHour , o.price , o.pay_price , o.refund_price , o.pay_type , s.wifi_info , s.kefu_phone , c.coupon_name , o.status , o.create_time from member_order_info o left join member_store_info s ON o.store_id = s.store_id left join member_room_info r ON r.room_id = o.room_id left join member_user m ON m.id = o.user_id left join member_coupon_info c ON o.coupon_id = c.coupon_id where o.deleted = 0
and o.order_id = #{orderId}
and o.user_id=#{userId} and o.end_time>now() and o.status in (0,1) order by o.end_time asc limit 1
